// Live end-to-end check of the E3 gate with the real Codex CLI (Linux, root).
//
//   CODEX_BIN=/path/to/native/codex node tests/live/codex-gate.live.ts [scenario ...]
//
// CODEX_BIN must be the native binary (in the npm package: node_modules/@openai/codex-linux-x64/vendor/<triple>/bin/codex),
// because the gate allowlists the host by /proc/<pid>/exe. Everything is real except the model: the gate service, the
// requirements file generated by src/gate/adapters/codex-requirements.ts, the production hook entry
// (src/gate/adapters/codex-hook.ts, started by Codex through `env -i`), and `codex exec`. The model is a local faux
// Responses API that plays a script and records what Codex sends it, so "did the Skill body reach the model" is
// observed directly.
//
// Codex reads /etc/codex/requirements.toml and admin Skills from /etc/codex/skills. The script re-runs itself in a
// private mount namespace and bind-mounts a temporary folder over /etc/codex, so the machine's own is never touched.
// Not part of `npm test`; prints one JSON report on stdout and exits 1 if any expectation failed.
import { execFileSync, spawn } from 'node:child_process';
import { existsSync, readdirSync, realpathSync, rmdirSync } from 'node:fs';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import http from 'node:http';
import path from 'node:path';
import { codexManagedConfigToml, codexRequirementsToml } from '../../src/gate/adapters/codex-requirements.ts';
import type { Mode } from '../../src/policy.ts';
import { asHostUser, gateWorld, handOver, HOST_USER, inPrivateMountNamespace, liveBase, liveRoot, MARK, NODE, overlay, writeSkill, type GateWorld } from './gate-world.ts';

const CODEX = process.env.CODEX_BIN ? realpathSync(process.env.CODEX_BIN) : '';
const ADMIN_ROOT = '/etc/codex';
const ADMIN_SKILLS = path.join(ADMIN_ROOT, 'skills');
const SKILLS = ['approved-skill', 'other-skill', 'project-skill', 'user-skill'];

// ---------- faux Responses API ----------
type Item = Record<string, unknown>;
type Step = (body: any) => Item[] | Promise<Item[]>;
let current: { steps: Step[]; requests: any[] } | null = null;
let callSeq = 0;
const say = (text: string): Item => ({ type: 'message', role: 'assistant', id: `msg_${++callSeq}`, content: [{ type: 'output_text', text, annotations: [] }] });
const shell = (cmd: string): Item => ({ type: 'function_call', id: `fc_${++callSeq}`, call_id: `call_${callSeq}`, name: 'exec_command', arguments: JSON.stringify({ cmd }) });

function fauxApi(): Promise<{ base: string; close: () => void }> {
  const server = http.createServer((req, res) => {
    let raw = '';
    req.on('data', (c) => (raw += c));
    req.on('end', async () => {
      if (req.method !== 'POST' || !req.url?.endsWith('/responses')) { res.writeHead(404); res.end('{}'); return; }
      const body = JSON.parse(raw);
      let items: Item[] = [say('done')];
      if (current) {
        current.requests.push(body);
        const step = current.steps[current.requests.length - 1];
        items = step ? await step(body) : [say('done')];
      }
      res.writeHead(200, { 'content-type': 'text/event-stream' });
      const ev = (type: string, d: object) => res.write(`event: ${type}\ndata: ${JSON.stringify({ type, ...d })}\n\n`);
      const id = `resp_${++callSeq}`;
      ev('response.created', { response: { id } });
      for (const item of items) ev('response.output_item.done', { item });
      ev('response.completed', { response: { id, usage: { input_tokens: 1, input_tokens_details: null, output_tokens: 1, output_tokens_details: null, total_tokens: 2 } } });
      res.end();
    });
  });
  return new Promise((resolve) => server.listen(0, '127.0.0.1', () => {
    const address = server.address() as { port: number };
    resolve({ base: `http://127.0.0.1:${address.port}/v1`, close: () => server.close() });
  }));
}

const textOf = (item: any): string => typeof item?.content === 'string' ? item.content
  : Array.isArray(item?.content) ? item.content.map((c: any) => c?.text ?? '').join('') : typeof item?.output === 'string' ? item.output : '';

/** Skill names in the "Available skills" list Codex shows the model. */
function listing(body: any): string[] {
  const text = (body.input ?? []).map(textOf).find((t: string) => t.includes('### Available skills')) ?? '';
  const section = text.slice(text.indexOf('### Available skills'));
  return [...section.matchAll(/^- ([A-Za-z0-9_.:-]+):/gmu)].map((m) => m[1]!);
}

/** Skill bodies Codex injected into the conversation (`<skill><name>…</name>`). */
function injected(body: any): string[] {
  return (body.input ?? []).map(textOf).flatMap((t: string) => [...t.matchAll(/<skill>\s*<name>([^<]+)<\/name>/gu)].map((m) => m[1]!));
}

function toolOutputs(body: any): string[] {
  return (body.input ?? []).filter((i: any) => i?.type === 'function_call_output').map((i: any) => textOf(i).slice(0, 240));
}

// ---------- the host's managed configuration ----------
type World = GateWorld & { base: string; unmount: () => Promise<void>; hookConfig: string };

async function world(base: string): Promise<World> {
  const root = await liveRoot('mago-live-cx-');
  // gate init writes the hook config and requirements.toml into <base>/etc/codex; the host reads them through this bind mount.
  const unmount = await overlay(ADMIN_ROOT, path.join(liveBase(root), 'etc', 'codex'));
  const w = await gateWorld(root, { host: 'codex', hostExe: CODEX });
  return Object.assign(w, { base, unmount, hookConfig: w.paths.hook });
}

// ---------- one codex exec run ----------
interface Run {
  prompt: string;
  steps?: Step[];
  /** Unapproved Skills to create: in the project (.agents/skills) and in the user's own folder (~/.codex/skills). */
  projectSkill?: boolean;
  userSkill?: boolean;
  /** A Skill planted in ~/.codex/skills/.system before Codex starts (the profile turns bundled Skills off). */
  plantedSystem?: boolean;
}

async function runCodex(w: World, name: string, run: Run) {
  const dir = path.join(w.root, 'runs', name);
  const home = path.join(dir, 'home');
  const codexHome = path.join(home, '.codex');
  const proj = path.join(dir, 'proj');
  for (const d of [codexHome, proj]) await mkdir(d, { recursive: true });
  if (run.projectSkill) await writeSkill(path.join(proj, '.agents', 'skills'), 'project-skill');
  if (run.userSkill) await writeSkill(path.join(codexHome, 'skills'), 'user-skill');
  await writeFile(path.join(codexHome, 'config.toml'),
    `model = "gpt-5.1-codex"\nmodel_provider = "faux"\n[model_providers.faux]\nname = "faux"\nbase_url = "${w.base}"\nwire_api = "responses"\nenv_key = "FAUX_KEY"\n`);
  // The requirements file, as the installer writes it for this user (deny_read needs the user's fixed Skill roots).
  await writeFile(path.join(ADMIN_ROOT, 'requirements.toml'), codexRequirementsToml({
    mode: w.mode, nodePath: NODE, hookEntry: w.hookEntry, configPath: w.hookConfig, hookTimeoutSec: 5, selfDeadlineMs: 3000,
    userSkillRoots: [path.join(codexHome, 'skills'), path.join(codexHome, 'skills', '.system'), path.join(home, '.agents', 'skills')],
  }), { mode: 0o644 });

  // The second managed file of the Codex profile (codex-profile.md C1): bundled and cloud Skills off, descriptions not injected.
  await writeFile(path.join(ADMIN_ROOT, 'managed_config.toml'), codexManagedConfigToml(), { mode: 0o644 });
  if (run.plantedSystem) await writeSkill(path.join(codexHome, 'skills', '.system'), 'planted-system-skill');

  handOver(dir);
  current = { steps: run.steps ?? [], requests: [] };
  const env = { PATH: process.env.PATH ?? '/usr/bin:/bin', HOME: home, CODEX_HOME: codexHome, FAUX_KEY: 'faux' };
  const [cmd, args] = asHostUser(CODEX, ['exec', '--json', '--skip-git-repo-check', '-s', 'workspace-write', run.prompt]);
  const child = spawn(cmd, args, { cwd: proj, env, stdio: ['ignore', 'pipe', 'pipe'] });
  let stdout = '';
  let stderr = '';
  child.stdout.on('data', (d) => (stdout += d));
  child.stderr.on('data', (d) => (stderr += d));
  const timer = setTimeout(() => child.kill('SIGKILL'), 120_000);
  const code = await new Promise<number | null>((r) => child.on('close', r));
  clearTimeout(timer);
  const requests = current.requests;
  current = null;
  const all = JSON.stringify(requests);
  const events = stdout.split('\n').filter(Boolean).map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
  return {
    exit: code,
    modelCalls: requests.length,
    listing: requests[0] ? listing(requests[0]) : null,
    injected: requests[0] ? injected(requests[0]) : [],
    reached: Object.fromEntries(SKILLS.map((n) => [n, all.includes(MARK(n))])),
    toolOutputs: requests.length ? toolOutputs(requests.at(-1)) : [],
    events: events.map((e: any) => (e.item ? `${e.type}:${e.item.type}:${String(e.item.text ?? e.item.message ?? e.item.command ?? '').slice(0, 200)}` : e.type)),
    stderr: stderr.split('\n').filter((l) => l && !/PATH aliases|Reading additional input/u.test(l)).slice(-6).join('\n').slice(0, 600),
  };
}

// ---------- scenarios ----------
type Outcome = Awaited<ReturnType<typeof runCodex>>;
interface Scenario {
  mode: Mode;
  what: string;
  before?: (w: World) => Promise<void>;
  run: (w: World) => Run;
  expect: (o: Outcome) => Record<string, boolean>;
  /** Properties the design document claims but this Codex does not provide: reported, never failing the run. */
  known?: (o: Outcome) => Record<string, boolean>;
}

const linked = (name: string) => `[$${name}](${ADMIN_SKILLS}/${name}/SKILL.md)`;
const blocked = (o: Outcome) => o.modelCalls === 0 || o.events.some((e) => /error|blocked/iu.test(e)) || /block|mago-ski/iu.test(o.stderr);

const SCENARIOS: Record<string, Scenario> = {
  'listing': {
    mode: 'enforce', what: 'the gate-installed admin Skill (a symlink in /etc/codex/skills) is listed; the user\'s own Skill is hidden by deny_read',
    run: () => ({ prompt: 'hello', projectSkill: true, userSkill: true }),
    expect: (o) => ({ 'approved-skill listed': o.listing?.includes('approved-skill') === true }),
    known: (o) => ({ 'user-skill hidden by deny_read': o.listing?.includes('user-skill') === false }),
  },
  'mention-linked-approved': {
    mode: 'enforce', what: 'a linked mention of the admin Skill is checked with the service and allowed; its body is injected',
    run: () => ({ prompt: `use ${linked('approved-skill')} now` }),
    expect: (o) => ({ 'approved body reached the model': o.reached['approved-skill'] === true }),
  },
  'mention-bare-approved': {
    mode: 'enforce', what: 'a bare $approved-skill (by design blocked whenever any non-admin Skill exists, e.g. Codex\'s own .system Skills)',
    run: () => ({ prompt: 'use $approved-skill now' }),
    // Codex writes its own bundled Skills to ~/.codex/skills/.system, so a machine without non-admin Skills does not exist:
    // the adapter (MASKING) then blocks every bare mention of an admin Skill. Only the linked form is usable.
    expect: (o) => ({ 'approved body did not reach the model (bare mention blocked)': o.reached['approved-skill'] === false }),
    known: (o) => ({ 'a bare mention of an admin Skill is usable': o.reached['approved-skill'] === true }),
  },
  'profile-planted-system': {
    mode: 'enforce', what: 'profile: a Skill planted in .system is reported, never failing (the managed config removes bundled Skills; whether a planted one is loaded is recorded)',
    run: () => ({ prompt: 'hello', plantedSystem: true }),
    expect: (o) => ({ 'the run completed': o.exit === 0 || o.modelCalls > 0 }),
    known: (o) => ({ 'planted .system Skill is not listed': o.listing?.includes('planted-system-skill') === false }),
  },
  'mention-project': {
    mode: 'enforce', what: 'a mention of a repo Skill is blocked; its body never reaches the model',
    run: () => ({ prompt: 'use $project-skill now', projectSkill: true }),
    expect: (o) => ({ 'project body did not reach the model': o.reached['project-skill'] === false, 'the prompt was blocked': blocked(o) }),
  },
  'mention-user': {
    mode: 'enforce', what: 'a mention of the user\'s own Skill is blocked; its body never reaches the model',
    run: () => ({ prompt: 'use $user-skill now', userSkill: true }),
    expect: (o) => ({ 'user body did not reach the model': o.reached['user-skill'] === false }),
  },
  'shell-read-project': {
    mode: 'enforce', what: 'the model runs `cat` on a repo Skill\'s SKILL.md: the PreToolUse (Bash) check refuses it (best-effort by design)',
    run: () => ({ prompt: 'hello', projectSkill: true, steps: [() => [shell('cat .agents/skills/project-skill/SKILL.md')], () => [say('done')]] }),
    expect: (o) => ({ 'project body did not reach the model': o.reached['project-skill'] === false }),
  },
  'revoked-new-session': {
    mode: 'enforce', what: 'after a revoke the Skill is auto-uninstalled: not listed, and a linked mention is blocked',
    before: async (w) => { await w.install('other-skill'); await w.revoke('other-skill'); },
    run: () => ({ prompt: `use ${linked('other-skill')} now` }),
    expect: (o) => ({ 'other-skill not listed': !(o.listing ?? []).includes('other-skill'), 'its body did not reach the model': o.reached['other-skill'] === false }),
  },
  'service-down': {
    mode: 'enforce', what: 'the gate service is stopped: a linked mention of the installed Skill is blocked (fail closed)',
    before: async (w) => { await w.stop(); },
    run: () => ({ prompt: `use ${linked('approved-skill')} now` }),
    expect: (o) => ({ 'approved body did not reach the model': o.reached['approved-skill'] === false, 'the prompt was blocked': blocked(o) }),
  },
  'shadow-project': {
    mode: 'shadow', what: 'shadow mode: a repo Skill mention is allowed and its body is injected',
    run: () => ({ prompt: 'use $project-skill now', projectSkill: true }),
    expect: (o) => ({ 'project body reached the model': o.reached['project-skill'] === true }),
  },
};

/**
 * Codex's workspace-write sandbox creates empty `.git`, `.agents` and `.codex` mount targets in its writable roots,
 * /tmp included. A /tmp/.git makes the Pi host tests treat /tmp as a project, so remove the ones this run created.
 */
const PLACEHOLDERS = ['.git', '.agents', '.codex'].map((name) => path.join('/tmp', name));
function removeCodexPlaceholders(existedBefore: Set<string>): void {
  for (const dir of PLACEHOLDERS) {
    if (existedBefore.has(dir) || !existsSync(dir)) continue;
    try {
      if (readdirSync(dir).length === 0) rmdirSync(dir);
    } catch {
      // Not ours to judge: leave anything that is not an empty directory.
    }
  }
}

async function main(): Promise<void> {
  const placeholdersBefore = new Set(PLACEHOLDERS.filter((dir) => existsSync(dir)));
  if (!CODEX) {
    console.log(JSON.stringify({ skipped: 'set CODEX_BIN to the native codex binary' }));
    return;
  }
  const api = await fauxApi();
  const w = await world(api.base);
  const pick = process.argv.slice(2);
  const report: unknown[] = [];
  let failed = 0;
  let started = false;
  try {
    for (const [name, scenario] of Object.entries(SCENARIOS)) {
      if (pick.length && !pick.includes(name)) continue;
      if (!started || w.mode !== scenario.mode) {
        await w.stop();
        await w.start(scenario.mode);
        await w.install('approved-skill');
        started = true;
      }
      await scenario.before?.(w);
      const outcome = await runCodex(w, name, scenario.run(w));
      const checks = scenario.expect(outcome);
      const knownGaps = scenario.known?.(outcome);
      const pass = Object.values(checks).every(Boolean);
      if (!pass) failed += 1;
      report.push({ scenario: name, mode: scenario.mode, what: scenario.what, pass, checks, ...(knownGaps ? { knownGaps } : {}), ...outcome });
      process.stderr.write(`${pass ? 'PASS' : 'FAIL'} ${name}\n`);
    }
  } finally {
    const status = await w.status().catch(() => null);
    await w.stop();
    api.close();
    await w.unmount();
    removeCodexPlaceholders(placeholdersBefore);
    if (process.env.MAGO_LIVE_KEEP !== '1') await rm(w.root, { recursive: true, force: true });
    console.log(JSON.stringify({
      codex: execFileSync(CODEX, ['--version'], { encoding: 'utf8' }).trim(), node: process.version, adminSkills: ADMIN_SKILLS, hostUser: HOST_USER ?? 'root',
      failed, scenarios: report, lastServiceStatus: status, keptAt: process.env.MAGO_LIVE_KEEP === '1' ? w.root : undefined,
    }, null, 2));
  }
  process.exitCode = failed ? 1 : 0;
}

await inPrivateMountNamespace(import.meta.url, main);
